// Presentación: lista de nombres de clientes para el encabezado del informe mensual.
function listaClientes(nombres) {
  return nombres.filter(Boolean).join(', ');
}
module.exports = { listaClientes };

{
  "_doc": "Manifiesto machine-readable del arnés. Lo leen los hooks de enforcement del plugin (hooks/) en cada PreToolUse. Es la fuente de verdad EJECUTABLE de las invariantes que en AGENTS.md están en prosa. Editar aquí cambia el enforcement en un solo sitio.",
  "arnes_version": "1.33.0",
  "agentes": {
    "_doc": "El nombre llega al hook en el campo `agent_type`. Sólo `agente_codigo` puede editar `codigo_app.globs`. Basta el nombre corto: el hook tolera el prefijo del plugin que Claude Code añade en runtime (`arnes-juan:desarrollador`). Escribirlo CON prefijo es opcional y hace la comparación estricta con ese proveedor.",
    "agente_codigo": "desarrollador",
    "conocidos": [
      "analista-requerimientos",
      "desarrollador",
      "qa-tester",
      "auditor-seguridad"
    ]
  },
  "codigo_app": {
    "_doc": "Rutas (relativas a la raíz) que SÓLO el agente de código puede editar. Apunta a código de PRODUCCIÓN; deja fuera tests y fixtures para que el qa-tester pueda editarlos. Patrones estilo shell; '*' abarca también separadores '/'. Ej.: \"src/*\", \"app/*\", \"lib/*\", \"*.py\".",
    "globs": [
      "src/*"
    ]
  },
  "quality_gates": [
    "true"
  ],
  "estados": {
    "completado": "completado",
    "todos": [
      "borrador",
      "pendiente",
      "en-progreso",
      "en-revisión",
      "completado",
      "bloqueado"
    ]
  },
  "estado_derivado": {
    "_doc": "Bloque de continuidad que el hook Stop/SubagentStop DERIVA leyendo el disco y escribe entre marcadores en `archivo`. No lo redacta ningún agente: un resumen escrito por el modelo miente justo cuando más falta hace, que es cuando le queda poco contexto. Fuera de los marcadores no se toca nada. Pon `activo: false` para apagarlo.",
    "activo": true,
    "archivo": "docs/ESTADO.md"
  },
  "veredictos": {
    "_doc": "APAGADO salvo que se encienda; un proyecto que no lo active no nota ningún cambio. `exigir_fecha`: un veredicto `aprobado` sin fecha (AAAA-MM-DD dentro de su paréntesis de evidencia: `QA: aprobado (R-045, 2026-09-01)`) no cierra el REQ. `caducan_con_codigo`: tampoco cierra un veredicto anterior al último commit que tocó `codigo_app.globs`, ni con cambios sin comitear en ese código; y sin repositorio git que consultar NO deja pasar, porque una puerta que no puede medir no deja pasar. La fecha sólo se le exige a `aprobado`, que es la única firma que cierra, y el empate del mismo día no caduca (`git log --format=%cs` tiene resolución de día). Antes de encenderlo en un proyecto con REQ ya firmados, mide con `tools/arnes-lectura.sh` cuántos veredictos llevan fecha: los que no la lleven no volverán a cerrar hasta re-validarse. Una fecha FUTURA se acepta y nunca caduca: esta puerta mide contra el código, no contra el reloj; falsearla es una violación declarada de la convención, como `aprobado (con reservas)`.",
    "exigir_fecha": false,
    "caducan_con_codigo": false
  },
  "campos": {
    "_doc": "APAGADO salvo que se encienda: con la llave apagada, la resolucion de la ausencia de un campo de cabecera decide EXACTAMENTE lo mismo que antes de esta version, REQ a REQ y decision a decision (REQ-024 CA-05, medido). Y esta llave no gobierna nada mas de la version: la cola de aprobaciones cambia SIN llave y para todos (REQ-024 CA-08/CA-09), asi que «no notar NINGUN cambio» seria falso y aqui no se promete. `ausencia_exige`: encendida, un campo de cabecera que NO llega a declararse deja de resolverse del lado que ABRE. QUE CUENTA COMO AUSENCIA lo decide una PROPIEDAD y no una lista de vias: la puerta no mide la VIA, mide que el campo no llegue a declararse. Comentarlo, borrarlo, no escribirlo nunca, o escribir su clave de forma que este lector no la lea como esa clave (`qa:` en minusculas, `Qa:`, `QÁ:`, o una letra sustituida por un homoglifo) son ejemplos NO EXHAUSTIVOS de la misma ausencia —esas cuatro formas de clave estan medidas con la llave encendida y las cuatro dan DENY nombrando `QA:`— y el sitio unico de las vias conocidas es `docs/seguridad/registro-seguridad.md`. Con la llave apagada, un `QA:`, un `Hallazgos abiertos:`, un `Sensible a seguridad:` o un `Rigor:` que faltan se perdonan por compatibilidad con los REQ anteriores a que los veredictos existieran —esos cuatro: son los que la medicion de REQ-024 CA-01 encontro ABRIENDO, 4 de las 6 claves del lector—, y por esa via un REQ critico cerraba con la validacion y la auditoria pendientes comentando UNA linea (SEC-047, medido). Con la llave encendida, cada campo se resuelve por la DIRECCION que declara su sitio unico (`ARNES_AUSENCIA` en `hooks/lib.sh`, ADR-009): `QA:` y `Hallazgos abiertos:` DENIEGAN nombrando el campo que falta, en CUALQUIER nivel de rigor —tambien en `ligero`, que sigue sin pedir el VEREDICTO de QA pero ya no exime de DECLARAR el campo (QA-024-01: hasta 1.34.0 la resolucion de `QA:` vivia DENTRO del corto-circuito de `ligero` y un REQ `ligero` sin `QA:` cerraba en ALLOW y sin diagnostico)—; `Sensible a seguridad:` y `Rigor:` GOBIERNAN con el valor que mas restringe (`si`, `critico`) en vez de retirarse; y `Seguridad:` tambien DENIEGA, pero su veredicto solo se lee cuando el rigor efectivo es `critico`, asi que por debajo de ese nivel su ausencia no para el cierre, igual que tampoco lo para su valor. `Estado` es n/a: es el sujeto de la transicion. CON LA LLAVE ENCENDIDA, NINGUNO DE LOS SEIS ABRE UNA PUERTA QUE SU VALOR DECLARADO HABRIA CERRADO —la clase derivada de REQ-024 CA-01 queda vacia—, Y ESO NO ES LO MISMO QUE DECIR QUE TODOS PARAN EL CIERRE: los que DENIEGAN lo paran en seco y nombran el campo; los que GOBIERNAN aplican el valor mas restrictivo, y entonces el REQ deja de cerrar solo si ese valor lo para. Medido: un REQ que omite `Sensible a seguridad:` y `Rigor:` pero ya lleva `QA: aprobado`, `Seguridad: aprobado` y `Hallazgos abiertos: (ninguno)` CIERRA, con rigor efectivo `critico`. ANTES DE ENCENDERLA mide con `tools/arnes-lectura.sh` —que da el NIVEL efectivo, la mitad de la respuesta y no la respuesta— y pregunta por ESTADO, no por via: cuales de tus REQ en estado terminal no cerrarian hoy — esa pregunta se responde por la PROPIEDAD y no depende de que ninguna lista de vias este completa. La friccion termina con alguien apagando el guard, asi que se enciende cuando el corpus esta listo. No cuesta ni un proceso: la llave viaja en la misma lectura del manifiesto que ya se hacia.",
    "ausencia_exige": false
  },
  "git": {
    "_doc": "Órdenes de git que NINGÚN agente ejecuta, ni siquiera la sesión coordinadora: descartan o esconden trabajo que puede no ser suyo. El trabajo de un subagente no es atómico para git —mientras escribe, el árbol contiene cambios intermedios de otros— y git no devuelve lo que nunca se comiteó (medido: ~52 archivos sin comitear perdidos en un incidente). ES LA ÚNICA PUERTA QUE NACE ENCENDIDA: las demás novedades cambian cómo se juzga algo y se activan a petición; ésta impide una operación irreversible cuyo valor legítimo dentro de una sesión de agentes es casi nulo. Se apaga con `activo: false` o se sustituye la lista. Cada regla es `subcomando [token...]`: el subcomando debe ser ése y cada token aparecer entre los argumentos, en cualquier posición; un flag corto casa dentro de un grupo (`clean -f` alcanza `-fd` y `-fdx`, no `-n`) y la forma LARGA del mismo flag casa igual que la corta, en los dos sentidos y con el valor pegado (`clean -f` alcanza `--force` y `--force=x`; `push --force` alcanza `push -f`); detrás de `--` ya no hay opciones, sólo rutas (`clean -- --force` es un archivo llamado así). El nombre viejo de un subcomando casa como el vigente: `stash save` es `stash push`. Una regla que es SÓLO el subcomando casa la forma desnuda, sin ningún argumento posicional: por eso `stash` deniega y `stash list` no. Mira el comando sin su texto: `git commit -m \"no uses git clean\"` no es un `git clean`.",
    "activo": true,
    "prohibidos": [
      "clean -f",
      "reset --hard",
      "checkout .",
      "restore .",
      "stash",
      "stash push",
      "stash pop",
      "stash drop",
      "stash clear"
    ]
  },
  "limites": {
    "_doc": "OPCIONAL, y casi nunca hace falta: el valor por defecto vive en el código. `bash_max_analisis` es el presupuesto en BYTES de material que el detector de escrituras analiza en un comando de shell (cuerpos de heredoc sin citar más el texto del comando). Por encima del techo el comando se DENIEGA sin analizar —una puerta que no puede medir no deja pasar—, así que subirlo sólo tiene sentido si un comando legítimo y grande topa con él. Sólo se acepta un entero positivo, y sólo puede SUBIR el techo del código: un valor más bajo no daría nada que la puerta no dé ya. Cualquier clave de este manifiesto con un tipo distinto del esperado (una cadena donde va un booleano, un decimal donde van bytes) cae al valor por defecto del arnés Y LO AVISA por stderr: caer del lado seguro está bien, hacerlo en silencio deja al proyecto creyendo que declaró algo. Bórralo si no lo necesitas.",
    "bash_max_analisis": 65536
  },
  "rotacion": {
    "_doc": "APAGADA salvo que se encienda: reestructurar un documento que escribió una persona no puede ser el comportamiento por defecto. Cuando un artefacto de bitácora supera `umbral_bytes`, el hook Stop MUEVE sus secciones sobrantes a `<nombre>-archivo.md` y deja un puntero. No resume ni reescribe: un resumen convertiría la bitácora en la versión que el modelo recuerda de la bitácora. Corta sólo en encabezados `## `; si no hay límites seguros, no hace nada. Y nunca borra: primero añade al destino, relee para comprobar que llegó, y sólo entonces recorta el origen.",
    "activo": false,
    "umbral_bytes": 262144,
    "conservar_secciones": 12,
    "_doc_orden": "Qué mitad es «lo viejo» NO se adivina. `nuevo-primero` (por defecto) es la convención del CHANGELOG: lo reciente arriba. Un registro cronológico que añade al final necesita `nuevo-al-final`. Equivocarse aquí archiva lo más RECIENTE, que es justo lo que hay que tener a mano. ESTOS VALORES SON EL DEFECTO: cada artefacto puede declarar el suyo, porque el orden es una propiedad DEL ARTEFACTO. Medido en un proyecto real: el CHANGELOG crece por arriba y el registro de seguridad por abajo, así que un solo orden dejaba la rotación inservible para uno de los dos.",
    "orden": "nuevo-primero",
    "_doc_artefactos": "Cadena u objeto, la misma convención que `quality_gates`. Una cadena hereda los ajustes de arriba; un objeto declara los suyos: { \"ruta\": \"docs/seguridad/registro.md\", \"orden\": \"nuevo-al-final\", \"umbral_bytes\": 100000, \"conservar_secciones\": 8 }. Un objeto con `glob` Y `seccion` rota UNA SECCIÓN de cada archivo que case, en vez del artefacto entero: { \"glob\": \"requirements/REQ-*.md\", \"seccion\": \"## Historial de cambios\", \"conservar_entradas\": 20, \"umbral_bytes\": 65536, \"orden\": \"nuevo-al-final\", \"archivo_dir\": \"requirements/historial\" }. Cuando esa sección supera `umbral_bytes`, mueve sus ENTRADAS viejas —con sus continuaciones— a `<archivo_dir>/<nombre>` (por defecto `historial/<nombre>` junto al documento) y deja un puntero FUERA de la tabla. QUÉ ES UNA ENTRADA, y no es una lista de prefijos: o una línea de lista a columna cero (`- `, `* `, `### `, `N. `), o una FILA DE DATOS de la tabla que ES la sección —su fila de cabecera y su separadora (`|---|---|`) seguidas y en el preámbulo, antes de cualquier otra entrada—. La cabecera y la separadora NUNCA son entradas: son preámbulo, se quedan en el documento, y cada bloque archivado se lleva su propia copia para que el destino siga leyéndose como tabla. Una tabla que vive DENTRO de una entrada es continuación y viaja con ella. Medido: hasta 1.33.0 esto sólo reconocía prefijos de lista y el corpus contra el que corre son tablas, así que el 23 % de `requirements/` era historia que la rotación no sabía mover. Y CUANDO NO PUEDE RESPONDER SIN AMBIGÜEDAD, NO ROTA Y AVISA —fail-closed, por stderr y con una línea propia en el bloque derivado de `docs/ESTADO.md`—: si el documento no contiene la sección declarada; si no tiene ni una entrada reconocible; si la estructura de la tabla es ambigua EN TODA LA EXTENSIÓN de la sección (dos tablas, otra separadora entre las filas de datos, o una línea que no es fila entre dos filas); si el documento o el archivo de historia no se pueden leer enteros (un byte NUL trunca la lectura, y publicar esa mitad borraría todo lo que viniera detrás); y si el documento CAMBIÓ entre leerlo y publicarlo, caso en el que no se publica NADA y se conserva la escritura ajena byte a byte. Con `estado_derivado.activo: false` la rotación DE SECCIÓN no rota: sin bloque derivado no queda constancia que sobreviva a la sesión, y un fail-closed invisible es indistinguible de una sección que lleva meses sin archivarse. El resto del documento NO SE TOCA: los criterios de aceptación son el contrato, y la cabecera con sus veredictos tampoco se puede alterar. El nombre de la sección se compara EXACTO, nunca por prefijo. Las seis claves: `glob`, `seccion`, `conservar_entradas` (20 por defecto), `umbral_bytes`, `orden` y `archivo_dir`. Qué sección es historia lo decide el proyecto: el arnés no trae ninguna por defecto.",
    "artefactos": []
  },
  "plantillas_origen": ".arnes/plantillas-origen",
  "requirements_dir": "requirements",
  "pending_approval": "PENDING_APPROVAL.md"
}

